// Lord's Treasure Chest of the active castles 193 / 194 / 195. Rules, sources and engine choices:
// src/game/siege-renew-chest-rules.js. The controller (server/world/siege-renew-controller.mjs) owns scenes and custody
// checks; this module owns the native catalog, the weekly durable record and the atomic claim.
//   Durable (social document): state.siegeRenew.castles[map].chest = {guild, name, startAt, regeneratedAt,
//     claimed: null | {at, ref, name, guild, items:[{itemIndex, count}]}}
//   regenerated by the controller's battle-end write (renewChestAfterEnd), claimed here in ONE socialTransaction that also
//   writes the lord's bag (users + social in the same CAS document). A failed write publishes nothing and keeps the chest.
import {randomUUID} from 'node:crypto';
import {socialTransaction,socialRef} from './social-state.mjs';
import {AuthoritativeInventory} from './inventory.mjs';
import {renewChestCatalog,rollRenewChest,RENEW_CHEST} from '../../src/game/siege-renew-chest-rules.js';

const cache=new WeakMap();
/** Validated native chest catalog (Map map -> entry) or null; cached per loaded data. */
export function siegeRenewChestData(world){
  const host=world?.data;if(!host||typeof host!=='object')return null;
  if(cache.has(host))return cache.get(host);
  let out=null;try{out=renewChestCatalog(host.dungeonData,host.progression?.boxes,host.itemDB||null);}catch{out=null;}
  cache.set(host,out);return out;
}
const refuse=([cate,code],status=409)=>{throw Object.assign(Error(`siege:${cate}:${code}`),{status,code:'SIEGE_RENEW_REFUSED'});};
const guildOfRef=(state,ref)=>Object.values(state?.guilds||{}).find(g=>g.members?.some(m=>m.ref===ref))||null;

/** The chest a player may see in a castle scene: native placement + this week's state (no roll, no odds secret). */
export function siegeRenewChestView(world,map,{inBattle=false}={}){
  const entry=siegeRenewChestData(world)?.get(Number(map));if(!entry)return null;
  const s=world.socialState?.siegeRenew?.castles?.[map],chest=s?.chest||null,owner=s?.owner?.guild||null;
  const ready=!!chest&&!chest.claimed&&chest.guild===owner&&!inBattle;
  return {trigger:entry.trigger,x:entry.x,z:entry.z,dir:entry.dir,name:entry.name,regeneratedAt:chest?.regeneratedAt||null,claimed:!!chest?.claimed,available:ready};
}

/** Distance (cells) from the player to the native chest cell centre. */
export function siegeRenewChestDistance(world,p,map){
  const entry=siegeRenewChestData(world)?.get(Number(map));
  return entry?Math.hypot(p.x-(entry.x+.5),p.z-(entry.z+.5)):Infinity;
}

/** One atomic claim. `check()` re-validates the controller's live custody inside the durable queue. The lord's bag and the
 * weekly record commit together; any refusal or storage failure leaves both unchanged. */
export async function claimSiegeRenewChest(world,p,{map,check,text}){
  const entry=siegeRenewChestData(world)?.get(Number(map));if(!entry)refuse(text.noInfo,503);
  // Lord (owner guild master) and an unclaimed chest of this week for the owner guild (guide 32).
  const verdict=(state,ref)=>{
    const s=state?.siegeRenew?.castles?.[map],g=guildOfRef(state,ref);
    if(!g)refuse(text.guildOnly,403);
    if(!s?.owner||s.owner.guild!==g.id)refuse(text.defendingOnly,403);
    if(g.master!==ref)refuse(text.leaderOnly,403);
    if(!s.chest||s.chest.claimed||s.chest.guild!==g.id)refuse(text.notYet);
    return {s,g};
  };
  // Ordinary refusals are answered from the live document before the durable queue (no write, no reload).
  verdict(world.socialState,socialRef(p));
  // A server-originated social intent: the controller supplies the revision of the document it is about to transact
  // (read inside the save queue), and a fresh request id. No client revision is trusted or required.
  const intent={get revision(){return world.socialState?.revision;},requestId:`renew-chest-${randomUUID()}`};
  return socialTransaction(world,p,intent,(state,profile,ref)=>{
    check();
    const {s,g}=verdict(state,ref),chest=s.chest;
    const items=rollRenewChest(entry,world.random);
    const bag=new AuthoritativeInventory(profile,world.data.itemDB,{now:world.now,random:world.random});
    for(const it of items)if(!bag.add(it.itemIndex,it.count))refuse(text.inventoryFull);
    const at=world.now();
    chest.claimed={at,ref,name:profile.name||p.profile?.name||null,guild:g.id,items:structuredClone(items)};
    s.history=[{at,kind:'chest',guild:g.id,ref,items:structuredClone(items)},...(s.history||[])].slice(0,20);
    return {map:Number(map),trigger:entry.trigger,items};
  });
}
/** ENGINE CHOICE: claim radius around the native chest cell (the controller's NPC service radius). */
export const SIEGE_RENEW_CHEST_RADIUS=RENEW_CHEST.radius;
